-- READ-ONLY cross-field variation within strict source-only timestamps intersecting WH1080 multirow zero-outTemp runs.
-- The same query was executed via Weather MCP SELECT. See saved aggregate snapshot for results.
WITH candidate AS (SELECT o.dateTime,w.outTemp,w.outHumidity,w.rain,w.rainRate,w.windSpeed,w.windGust,w.barometer FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1451606400 AND o.dateTime<1514764800 AND r.dateTime IS NULL AND o.dateTime%300=0 AND o.usUnits=17 AND w.usUnits=17 AND o.`interval`=5 AND w.`interval`=5), w AS (SELECT dateTime,`interval` interval_min,usUnits,outTemp,LAG(dateTime) OVER(ORDER BY dateTime) prev_ts,LAG(outTemp) OVER(ORDER BY dateTime) prev_temp FROM weewx_WH1080.archive WHERE dateTime>=1451606400 AND dateTime<1514764800), marked AS (SELECT *,CASE WHEN outTemp=0 AND prev_temp=0 AND dateTime-prev_ts<=600 THEN 0 ELSE 1 END starts_new FROM w), grouped AS (SELECT *,SUM(starts_new) OVER(ORDER BY dateTime ROWS UNBOUNDED PRECEDING) grp FROM marked), zero_runs AS (SELECT grp,COUNT(*) n FROM grouped WHERE outTemp=0 GROUP BY grp HAVING n>=2), candidate_groups AS (SELECT c.*,g.grp FROM candidate c JOIN grouped g ON g.dateTime=c.dateTime JOIN zero_runs z ON z.grp=g.grp) SELECT CASE WHEN dateTime<1483228800 THEN 2016 ELSE 2017 END utc_year,COUNT(*) selected_rows,COUNT(DISTINCT outTemp) outTemp_distinct,MIN(outTemp) min_outTemp,MAX(outTemp) max_outTemp,SUM(outHumidity IS NOT NULL) outHumidity_nonnull,COUNT(DISTINCT outHumidity) outHumidity_distinct,SUM(rain IS NOT NULL) rain_nonnull,COUNT(DISTINCT rain) rain_distinct,SUM(rainRate IS NOT NULL) rainRate_nonnull,COUNT(DISTINCT rainRate) rainRate_distinct,SUM(windSpeed IS NOT NULL) windSpeed_nonnull,COUNT(DISTINCT windSpeed) windSpeed_distinct,SUM(windGust IS NOT NULL) windGust_nonnull,COUNT(DISTINCT windGust) windGust_distinct,SUM(barometer IS NOT NULL) barometer_nonnull,COUNT(DISTINCT barometer) barometer_distinct FROM candidate_groups GROUP BY utc_year ORDER BY utc_year;
